// Generated by `hdr install pi`. Reinstall rather than edit: HDR checks this
// file byte for byte and reports any other content as an unregistered hook.
import assert from "node:assert"
import { spawnSync } from "node:child_process"

const COMMAND = __HDR_COMMAND__

function runChecker(payload) {
  assert(payload.hook_event_name && payload.session_id, "HDR payload needs an event and session")
  const run = spawnSync(COMMAND[0], COMMAND.slice(1), {
    input: JSON.stringify(payload),
    encoding: "utf8",
    timeout: 15000,
  })
  if (run.error || run.status !== 0) {
    // Fail closed: a checker that cannot run must not silently allow tool calls.
    return { deny: `HDR ERROR: ${run.stderr || run.error}` }
  }
  const out = run.stdout.trim() ? JSON.parse(run.stdout) : {}
  const specific = out.hookSpecificOutput || {}
  assert(typeof out === "object", `HDR returned non-object output: ${run.stdout}`)
  return {
    deny: specific.permissionDecision === "deny" ? specific.permissionDecisionReason : undefined,
    block: out.decision === "block" ? out.reason : undefined,
    context: specific.additionalContext,
    message: out.systemMessage,
  }
}

export default function (pi) {
  let context
  let stopBlocked = false
  const base = (name, ctx) => {
    assert(ctx.cwd, `pi gave HDR ${name} no working directory`)
    const payload = { hook_event_name: name, session_id: ctx.sessionManager.getSessionId(), cwd: ctx.cwd }
    assert(payload.session_id, `pi gave HDR ${name} no session ID`)
    return payload
  }
  const notify = (ctx, message) => {
    assert(typeof message === "string" && message, "HDR notification must be text")
    if (ctx.hasUI) ctx.ui.notify(message, message.startsWith("HDR PASS") ? "info" : "warning")
    assert(ctx.ui || !ctx.hasUI, "pi reported a UI without a UI context")
  }

  pi.on("session_start", async (event, ctx) => {
    const result = runChecker({ ...base("SessionStart", ctx), source: event.reason })
    context = result.context
    if (result.message) notify(ctx, result.message)
  })

  pi.on("before_agent_start", async () => {
    if (!context) return undefined
    const message = { customType: "hdr", content: context, display: false }
    context = undefined
    return { message }
  })

  pi.on("tool_call", async (event, ctx) => {
    const result = runChecker({
      ...base("PreToolUse", ctx),
      tool_name: event.toolName,
      tool_use_id: event.toolCallId,
      tool_input: event.input,
    })
    return result.deny ? { block: true, reason: result.deny } : undefined
  })

  pi.on("tool_result", async (event, ctx) => {
    const result = runChecker({
      ...base("PostToolUse", ctx),
      tool_name: event.toolName,
      tool_use_id: event.toolCallId,
      tool_input: event.input,
    })
    if (!result.block) return undefined
    return { content: [...event.content, { type: "text", text: result.block }] }
  })

  pi.on("agent_end", async (event, ctx) => {
    // Mirrors Claude's stop_hook_active: ask for one correction, then return control.
    const result = runChecker({ ...base("Stop", ctx), stop_hook_active: stopBlocked })
    stopBlocked = Boolean(result.block)
    if (result.block) pi.sendUserMessage(result.block, { deliverAs: "followUp" })
    else if (result.message) notify(ctx, result.message)
  })
}
